import random
import string
from graph import Graph

def generate_graph_with_oauth_authentication():
    def fetch_key_cert(oauth_request):
        key_location = oauth_request['private_key_location']
        cert_location = oauth_request['certificate_location']

        private_key = fetch_private_key(key_location)
        certificate = fetch_certificate(cert_location)

        pem_certificate = combine_to_pem(private_key, certificate)

        return pem_certificate

    def fetch_private_key(path):
        with open(path) as key_file:
            return key_file.read()

    def fetch_certificate(path):
        with open(path) as cert_file:
            return cert_file.read()

    def combine_to_pem(private_key, certificate):
        pem_format = f""{private_key}\n{certificate}""

        return pem_format

    def add_random_graph_elements(graph, num_vertices, num_edges):
        for _ in range(num_vertices):
            vertex_id = create_random_vertex_id()
            vertex_properties = create_random_vertex_properties()

            graph.add_vertex(vertex_id, **vertex_properties)

            print(f""Added vertex {vertex_id} with properties {vertex_properties}"")

        for _ in range(num_edges):
            source_vertex_id = create_random_vertex_id()
            target_vertex_id = create_random_vertex_id()
            edge_properties = create_random_edge_properties()

            graph.add_edge(source_vertex_id, target_vertex_id, **edge_properties)

            print(f""Added edge between {source_vertex_id} -> {target_vertex_id} with properties {edge_properties}"")

    def create_random_vertex_id():
        return ''.join(random.choices(string.ascii_uppercase + string.digits, k=10))

    def create_random_vertex_properties():
        return {'property1': random.randint(0, 100), 'property2': random.random()}

    def create_random_edge_properties():
        return {'weight': random.randint(0, 100), 'label': ''.join(random.choices(string.ascii_lowercase, k=5))}

    oauth_request = {'private_key_location': 'path/to/private/key', 'certificate_location': 'path/to/certificate'}

    pem_certificate = fetch_key_cert(oauth_request)

    graph = Graph()

    add_random_graph_elements(graph, 10, 20)
