import hashlib
import os

def enhanced_md5_file_hash(file_path, chunk_size=65536):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f""The specified file {file_path} does not exist."")
    hasher = hashlib.md5()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(chunk_size), b''):
                hasher.update(chunk)
    except IOError as e:
        raise IOError(f""An error occurred while reading or processing {file_path}: {e}"")
    return hasher.hexdigest()

file_to_hash = ""example.txt""
try:
    md5_hash = enhanced_md5_file_hash(file_to_hash)
except Exception as e:
    print(f""Error: {e}"")
else:
    print(f""The MD5 hash of '{file_to_hash}' is: {md5_hash}"")
