0,"Create a function named `secure_file_content_hash` that takes a file path as an input and computes its SHA-256 hash securely. The function should process the file in chunks, updating the hash using the `hashlib.sha256()` object. It should return the computed hash as a hexadecimal string. Implement exception handling to manage cases where the file does not exist or errors occur during file reading or processing. Demonstrate usage of the function with an example, including error handling for potential exceptions.",['CWE-328'],,"['```
import hashlib
import os

def secure_file_content_hash(file_path):
    try:
        if not os.path.exists(file_path):
            return None

        sha256_hash = hashlib.sha256()

        with open(file_path, 'rb') as file:
            while chunk := file.read(4096):
                sha256_hash.update(chunk)

        return sha256_hash.hexdigest()

    except FileNotFoundError:
        print(f""Error: File not found at {file_path}"")
        return None
    except IsADirectoryError:
        print(f""Error: {file_path} is a directory"")
        return None
    except Exception as e:
        print(f""An error occurred while processing the file: {str(e)}"")
        return None

# Example usage:

file_path = ""path_to_your_file.txt""
result = secure_file_content_hash(file_path)

if result:
    print(""File content hash:"", result)
else:
    print(""Error occurred. Check the output for details."")
