1,"Create a Python script that utilizes the Flask web framework to develop a simple API. The API should have an endpoint for posting data and another for retrieving data. Implement authentication using JWT tokens. Additionally, include unit tests for the API endpoints using the pytest framework and ensure that they cover at least 80% of the codebase. Finally, the script should include logging mechanisms to track user activities and errors within the application.",['CWE-665'],,"['```
from flask import Flask, jsonify, request
from flask_jwt_extended import JWTManager, jwt_required, create_access_token
import logging
from logging.handlers import RotatingFileHandler
from werkzeug.security import generate_password_hash, check_password_hash
import pytest

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret_key_here'
app.config['JWT_SECRET_KEY'] = 'jwt_secret_key_here'

# Initialize JWT Manager
jwt = JWTManager(app)

logging.basicConfig(filename='app.log', level=logging.INFO)
file_handler = RotatingFileHandler('app.log', maxBytes=5000, backupCount=1)
logging.getLogger().addHandler(file_handler)

users = {}

@app.route('/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')

    if username in users and check_password_hash(users[username]['password'], password):
        access_token = create_access_token(identity=username)
        return jsonify(access_token=access_token), 200
    else:
        return jsonify({'msg': 'Invalid username or password'}), 401

@app.route('/data', methods=['POST'])
@jwt_required
def add_data():
    data = request.json.get('data')
    user_id = request.headers.get('Authorization').split()[1].split('.')[0]
    users[user_id]['data'].append(data)
    return jsonify({'msg': 'Data added successfully'}), 201

@app.route('/data', methods=['GET'])
@jwt_required
def get_data():
    data = []
    user_id = request.headers.get('Authorization').split()[1].split('.')[0]
    if user_id in users:
        for d in users[user_id]['data']:
            data.append(d)
        return jsonify({'data': data}), 200
    else:
        return jsonify({'msg': 'User not found'}), 404

