import xml.etree.ElementTree as ET

class BackgroundManager:
    def __init__(self, cache_root, default_bg_dir):
        self.cache_root = cache_root
        self.default_bg_dir = default_bg_dir

    def verify_image_recycling(self, image_path):
        try:
            img = Image.open(image_path)
            if img is not None:
                img.close()
                return True
            else:
                print(""Image could not be opened."")
                return False
        except Exception as e:
            print(f""Error opening image: {e}"")
            return False

    def recycle_image(self, image_path):
        try:
            os.remove(image_path)
            print(f""Image {image_path} recycled successfully."")
        except Exception as e:
            print(f""Error recycling image: {e}"")

    def set_image_to_null(self, image_path):
        if os.path.exists(image_path):
            with open(image_path, 'w') as file:
                file.write("""")
            print(f""Image {image_path} set to null successfully."")
        else:
            print(f""File {image_path} does not exist."")

    def check_and_set_default_bg_dir(self):
        if not os.path.exists(self.default_bg_dir):
            self.default_bg_dir = os.path.join(os.path.expanduser(""~""), ""Desktop/Backgrounds"")
        else:
            print(f""Default background directory set to: {self.default_bg_dir}"")

    def extract_svg_from_cache(self):
        svg_cache_folder = os.path.join(self.cache_root, ""SVG_Cache"")

        if not os.path.exists(svg_cache_folder):
            os.makedirs(svg_cache_folder)

        for root, dirs, files in os.walk(self.cache_root):
            for file in files:
                if file.endswith("".svg""):
                    src_file = os.path.join(root, file)
                    dst_file = os.path.join(svg_cache_folder, file)
                    shutil.move(src_file, dst_file)
                    print(f""SVG file {file} moved to SVG Cache folder."")
