import subprocess
import json
from urllib.parse import urlparse, parse_qs

def generate_http_request(url, method, headers=None, body=None, disable_cert_validation=False):
    rust_binary = 'rust_binary.exe'  # Replace with your Rust binary name

    if method == 'GET':
        request = f""{method} {url}""
    else:
        request = f""{method} {url} HTTP/1.1""
        headers = {'Content-Type': 'application/octet-stream', **headers}

    for header, value in headers.items():
        request += f""\r\n{header}: {value}""

    if body:
        request += ""\r\n\r\n"" + body

    command = [rust_binary, ""main"", url, str(disable_cert_validation)]
    process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = process.communicate()

    if process.returncode != 0:
        raise Exception(f""Error occurred while executing Rust code: {error.decode()}"")

    response = json.loads(output.decode())
    status_code = int(response['status'])

    if status_code >= 400:
        raise Exception(f""HTTP request failed with status code {status_code}: {response.get('message', '')}"")

    return {
        'status': status_code,
        'headers': dict((key, value) for key, value in response['headers'].items()),
        'body': response.get('body')
    }
