class TemperatureMonitor:
    def __init__(self):
        self.temperature_readings = []

    def add_temperature_reading(self, timestamp, temperature):
        if timestamp - self.temperature_readings[0][0] >= 86400:  # 24 hours
            self.temperature_readings.pop(0)
        self.temperature_readings.append((timestamp, temperature))

    def calculate_average_temperature(self):
        total_temp = sum(temperature for _, temperature in self.temperature_readings)
        return total_temp / len(self.temperature_readings)

# Example usage:
