import csv
import xlsxwriter
from pathlib import Path
from tqdm import tqdm
import sys

def convert_csv_to_excel(csv_file, output_file, sheet_name=None):
    if not Path(csv_file).is_file():
        print(f""Error: {csv_file} does not exist."")
        return

    try:
        with open(csv_file, 'r') as file:
            reader = csv.DictReader(file)
            data = [row for row in reader]

        if len(sys.argv) > 3 and sys.argv[3]:
            filter_criteria = {
                'column': int(sys.argv[3].split(':')[0]),
                'operator': sys.argv[3].split(':')[1],
                'value': sys.argv[3].split(':')[2]
            }
            data = [row for row in data if eval(f""row['{filter_criteria['column']}'] {filter_criteria['operator']} '{filter_criteria['value']}'"")]

        workbook = xlsxwriter.Workbook(output_file)
        worksheet = workbook.add_worksheet()
        header = ['' for _ in range(len(data[0]))]
        for i, row in enumerate(data):
            for j, value in enumerate(row.values()):
                worksheet.write(i+1, j, value)
            if i == 0:
                for j, field_name in enumerate(header):
                    worksheet.write(0, j, field_name)

        workbook.close()
    except Exception as e:
        print(f""Error: {str(e)}"")
