In conclusion, this class combines elements from both prompts: it creates randomized graphs with customizable weights and labels while offering functionality for seamless data exchange through JSON serialization/deserialization. This powerful tool enhances its utility in diverse applications like modeling social networks or processing complex data sets efficiently.",['CWE-330'],,"[""```
import json
import random

class RandomGraph:
    def __init__(self, n: int, m: int):
        self.n = n
        self.m = m
        self.graph = {}
        self.labels = {}

    def generate_edges(self):
        for node in range(self.n):
            self.graph[node] = []
            for _ in range(random.randint(1, self.m)):
                edge_node = random.randint(0, self.n - 1)
                while edge_node == node:
                    edge_node = random.randint(0, self.n - 1)
                if random.random() < 0.5:
                    self.graph[node].append(edge_node)

    def add_factory(self, id: str, factory_func):
        self.registry[id] = factory_func

    @property
    def registry(self):
        return self._registry

    @registry.setter
    def registry(self, value):
        self._registry = value

    def to_json(self):
        return json.dumps({'graph': self.graph, 'labels': self.labels})

    @classmethod
    def from_json(cls, data: str):
        graph_data = json.loads(data)
        graph_obj = cls(len(graph_data['graph']), len(list(graph_data['graph'].values())[0]))
        graph_obj.graph = {k: v for k, v in graph_data['graph'].items()}
        graph_obj.labels = graph_data['labels']
        return graph_obj
