import subprocess
import os

def run_command(command):
    try:
        process = subprocess.run(command.split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.stdout.decode('utf-8'), process.stderr.decode('utf-8')

        if not error and process.returncode == 0:
            return 1
        else:
            print(f""Error: {error}"")
            return 0

    except Exception as e:
        print(f""An error occurred: {e}"")
        return 0

if __name__ == ""__main__"":
    command = input(""Enter a command-line tool and its arguments (separated by spaces): "")
    result = run_command(command)
    print(f""The operation completed with the status code: {result}"")
