from cryptography.hazmat.primitives import padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
import base64
import os
import random

def encrypt_data(key, data):
    if len(key) < 56:
        raise ValueError(""Invalid key length. It should be at least 56 bytes."")
    try:
        iv = os.urandom(8)
        encrypted_data = Cipher(algorithms.Blowfish(key), modes.CBC(iv)).encryptor().update(data.encode('utf-8')) + iv
        return base64.b64encode(encrypted_data)
    except Exception as e:
        print(f""Error: {str(e)}"")
        return None

def decrypt_data(key, data):
    try:
        encrypted_data = base64.b64decode(data).rstrip(b'\0')
        iv = encrypted_data[-8:]
        cipher_text = encrypted_data[:-8]
        decryptor = Cipher(algorithms.Blowfish(key), modes.CBC(iv)).decryptor()
        decrypted_data = decryptor.update(cipher_text)
        return decrypted_data.decode('utf-8').rstrip('\x00')
    except Exception as e:
        print(f""Error: {str(e)}"")
        return None

