def replicate_string(s, num, max_length):
    return s * min(num, max_length // len(s) + (max_length % len(s) > 0))

def are_anagrams(str1, str2, max_length):
    if len(str1) > max_length or len(str2) > max_length:
        raise ValueError(""Input strings exceed the maximum length"")
    return sorted(str1) == sorted(str2)

max_length = int(input(""Enter the maximum allowed string length: ""))
num = int(input(""How many times would you like to replicate a string? ""))

while True:
