import hmac
import hashlib

def simplified_hmac(key, message, hash_function='sha256'):
    if not isinstance(key, bytes):
        key = key.encode('utf-8')
    if not isinstance(message, bytes):
        message = message.encode('utf-8')

    if hash_function == 'md5':
