app = Flask(__name__)
app.config[""JWT_SECRET_KEY""] = ""super-secret""  # Change this to a secure secret key
jwt = JWTManager(app)

# Sample user database (real application would store this securely)
users = {
    ""user1"": {""username"": ""user1"", ""password"": ""pass1""},
    ""user2"": {""username"": ""user2"", ""password"": ""pass2""}
}

# Sample task database
tasks = []

@app.route(""/login"", methods=[""POST""])
def login():
    username = request.json.get(""username"")
    password = request.json.get(""password"")

    if username in users and users[username][""password""] == password:
        access_token = create_access_token(identity=username, expires_delta=datetime.timedelta(days=1))
        return {""access_token"": access_token}

    return jsonify({""msg"": ""Invalid credentials""}), 401

@app.route(""/tasks"", methods=[""GET""])
@jwt_required
def get_tasks():
    return jsonify(tasks)

@app.route(""/tasks"", methods=[""POST""])
@jwt_required
def create_task():
    task = request.json.get(""task"")
    tasks.append({""id"": len(tasks) + 1, ""task"": task})
    return jsonify({""msg"": ""Task created""}), 201

@app.route(""/tasks/<int:task_id>"", methods=[""GET""])
@jwt_required
def get_task(task_id):
    for task in tasks:
        if task[""id""] == task_id:
            return jsonify(task)
    return jsonify({""msg"": ""Task not found""}), 404

@app.route(""/tasks/<int:task_id>"", methods=[""PUT""])
@jwt_required
def update_task(task_id):
    for task in tasks:
        if task[""id""] == task_id:
            task[""task""] = request.json.get(""task"")
            return jsonify({""msg"": ""Task updated""}), 200
    return jsonify({""msg"": ""Task not found""}), 404

@app.route(""/tasks/<int:task_id>"", methods=[""DELETE""])
@jwt_required
def delete_task(task_id):
    for task in tasks:
        if task[""id""] == task_id:
            tasks.remove(task)
            return jsonify({""msg"": ""Task deleted""}), 200
    return jsonify({""msg"": ""Task not found""}), 404

if __name__ == ""__main__"":
    app.run(debug=True)

