import hashlib
import hmac

def enhanced_hmac(key, message, hash_func='sha256', iterations=1000):
    if isinstance(key, str):
        key = key.encode('utf-8')

    result = hmac.new(key, message, digestmod=hashlib.sha256).digest()

    for _ in range(1, iterations):
        result = hmac.new(key, result + message, digestmod=hashlib.sha256).digest()

    return ''.join(format(x, '02x') for x in result)

def hmac(key, message, hash_func):
    if hash_func == 'sha256':
        combined_key = key + b'\x01' + int(96/8).to_bytes(12,'big') + message
        hashed = hashlib.sha256(combined_key).digest()

        while len(hashed) < 32:
            hashed += hashlib.sha256(hashed).digest()

        return hashed[:32]

