import hashlib
import xml.etree.ElementTree as ET

def md5_hash(file_path):
    hash_md5 = hashlib.md5()
    chunk_size = 1024 * 1024  # 1MB chunk size

    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hash_md5.update(data)

    return hash_md5.hexdigest()

def find_element_by_name(xml_file_path, element_name):
    try:
        tree = ET.iterparse(xml_file_path)
        root = next(tree)
        elements = root.findall('.//' + element_name)

        if len(elements) == 1:
            return elements[0]
        elif len(elements) > 1:
            raise Exception(f'Multiple elements found with name ""{element_name}""')
        else:
            raise Exception(f'No element found with name ""{element_name}""')

    except ET.ParseError as e:
        raise Exception(f'Error parsing XML: {e}')

def parse_xml_and_find_element(file_path, xpath_query):
    file_hash = md5_hash(file_path)
    xml_element = find_element_by_name(file_path, xpath_query)

    return {'hash': file_hash, 'element': xml_element}
