@app.route('/resource/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if resource_id in resources:
        data = request.get_json()
        resources[resource_id]['name'] = data['name']
        resources[resource_id]['data'].update(data['data'])
        return jsonify(resources[resource_id]), 200
    else:
        return jsonify({'error': 'Resource not found'}), 404

@app.route('/resource/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if resource_id in resources:
        del resources[resource_id]
        default_resource = {'name': 'Default Resource', 'data': {'key1': 'default_value'}}
        return jsonify(default_resource), 200
    else:
        return jsonify({'error': 'Resource not found'}), 404

if __name__ == '__main__':
