0,"Design a Python function that communicates with a specified FTP server using the ftplib library, handles different FTP status codes, and logs the interaction history. The function should accept the FTP server's URL, username, and password as inputs and output a dictionary containing the transferred file details. It should also gracefully handle connection timeouts and network errors, providing appropriate error messages.",['CWE-918'],,"['```
import ftplib
from ftplib import FTP_PORT
from datetime import datetime

def ftp_file_transfer(ftp_url, username, password):
    try:
        ftp = ftplib.FTP()
        ftp.connect((ftp_url.split('//')[1].split(':')[0], FTP_PORT))
        ftp.login(user=username, passwd=password)

        transferred_files = {}

        for file in ftp.nlst():
            if not file.endswith('/'):
                with open(file, 'wb') as local_file:
                    ftp.retrbinary('RETR '+file, local_file.write)
                transferred_files[file] = {'size': int(ftp.size(file)), 'downloaded_at': datetime.now()}

        ftp.quit()

        return transferred_files

    except ftplib.all_errors as e:
        if isinstance(e, ftplib.error_temp):
            error_message = ""Connection timed out. FTP server is not available.""
        elif isinstance(e, ftplib.error_perm):
            error_message = f""Error: {e}""
        else:
            error_message = ""Network error occurred during the file transfer operation.""

        print(f""{error_message}. No files were transferred."")

    return {}
