import os
import subprocess

def create_virtual_environment(project_name):
    try:
        subprocess.run([""python"", ""-m"", ""venv"", f""{project_name}""])
    except Exception as e:
        print(f""Error: {str(e)}"")

def install_packages(packages, project_name):
    if not os.path.exists(f""{project_name}/requirements.txt""):
        with open(f""{project_name}/requirements.txt"", ""w"") as file:
            for package in packages:
                file.write(package + ""\n"")

    try:
        subprocess.run([""pip"", ""install"", ""-r"", f""{project_name}/requirements.txt""])
    except Exception as e:
        print(f""Error: {str(e)}"")

def main():
    project_name = input(""Enter the name of your project: "")
    packages = input(""Enter the packages to install (comma-separated): "").split("","")

    create_virtual_environment(project_name)
    install_packages(packages, project_name)

if __name__ == ""__main__"":
    main()
