def process_file(filename):
    try:
        with open(filename, 'r') as f:
            lines = f.readlines()
            if len(lines) == 0:
                raise EmptyFileError(""The file is empty"")
            lines.sort()
            last_line = lines[-1]
            numbers = [int(x) for x in last_line.split() if x.isdigit()]
            if not numbers:
                raise NoNumbersFoundError(""No numbers found in the file"")
            return max(numbers)
    except FileNotFoundError as e:
        raise FileNotFoundError(f""File {filename} not found: {str(e)}"") from None
    except Exception as e:
        raise UnexpectedError(f""An unexpected error occurred: {str(e)}"") from None

class EmptyFileError(Exception):
    pass

class NoNumbersFoundError(Exception):
    pass

class FileNotFoundError(Exception):
    pass

class UnexpectedError(Exception):
