import datetime as dt
import matplotlib.pyplot as plt
from collections import defaultdict

class TemperatureSensor:
    def __init__(self):
        self.readings = []
        self.name = None

    def add_reading(self, timestamp, temperature, unit='Celsius'):
        if isinstance(timestamp, int) and isinstance(temperature, (int, float)):
            self.readings.append({'timestamp': timestamp, 'temperature': temperature, 'unit': unit})
            return True
        else:
            return False

    def get_average_temperature(self):
        if not self.readings:
            return 0.0
        return sum([r['temperature'] for r in self.readings]) / len(self.readings)

    def plot_readings(self, title='Temperature Readings'):
        timestamps = [r['timestamp'] for r in self.readings]
        temperatures = [r['temperature'] for r in self.readings]
        plt.plot(timestamps, temperatures)
        plt.xlabel('Timestamp')
        plt.ylabel(f'Temperature ({self.readings[0][""unit""]})')
        plt.title(title)
        plt.show()

class TemperatureReader:
    def __init__(self):
        self.sensors = defaultdict(TemperatureSensor)

    def add_sensor(self, name):
        self.sensors[name] = TemperatureSensor()
        return True

    def remove_sensor(self, name):
        if name in self.sensors:
            del self.sensors[name]
            return True
        else:
            return False

    def get_sensors(self):
        return list(self.sensors.keys())

    def add_reading(self, sensor_name, timestamp, temperature, unit='Celsius'):
        if sensor_name in self.sensors:
            sensor = self.sensors[sensor_name]
            if sensor.add_reading(timestamp, temperature, unit):
                return True
            else:
                return False
        else:
            return False

    def get_average_temperature(self, sensor_name):
        if sensor_name in self.sensors:
            sensor = self.sensors[sensor_name]
            return sensor.get_average_temperature()
        else:
            return None

    def plot_readings(self, sensor_name, title='Temperature Readings'):
        if sensor_name in self.sensors:
            sensor = self.sensors[sensor_name]
            sensor.plot_readings(title)
        else:
            print(""Sensor not found."")

reader = TemperatureReader()

while True:
    print(""\nTemperature Reader Menu:"")
    print(""1. Add Sensor"")
    print(""2. Remove Sensor"")
    print(""3. Add Reading"")
    print(""4. Get Average Temperature"")
    print(""5. Plot Readings"")
    print(""6. Exit"")

    choice = input(""Choose an option: "")

    if choice == '1':
        name = input(""Enter sensor name: "")
        reader.add_sensor(name)
    elif choice == '2':
        name = input(""Enter sensor name to remove: "")
        reader.remove_sensor(name)
    elif choice == '3':
        sensor_name = input(""Enter sensor name: "")
        timestamp = int(input(""Enter timestamp (seconds since epoch): ""))
        temperature = float(input(""Enter temperature value: ""))
        unit = input(""Enter unit of measurement (Celsius/Fahrenheit): "")
        reader.add_reading(sensor_name, timestamp, temperature, unit)
    elif choice == '4':
        sensor_name = input(""Enter sensor name: "")
        print(f""Average Temperature for Sensor '{sensor_name}': {reader.get_average_temperature(sensor_name)}"")
    elif choice == '5':
        sensor_name = input(""Enter sensor name: "")
        reader.plot_readings(sensor_name)
    elif choice == '6':
        break
    else:
        print(""Invalid option. Please choose a valid option."")
