def calculate_cart_cost():
    cart = {}
    total_cost = 0
    while True:
        item_name = input(""Enter the item name (or 'done' to finish): "")
        if item_name.lower() == 'done':
            break
        try:
            price = float(input(f""Enter the price of {item_name}: ""))
        except ValueError:
            print(""Invalid price. Please enter a number."")
            continue
        try:
            quantity = int(input(f""Enter the quantity of {item_name} (0 or more): ""))
        except ValueError:
            print(""Invalid quantity. Please enter an integer."")
            continue
        cart[item_name] = {'price': price, 'quantity': quantity}
    for item in cart.values():
        total_cost += item['price'] * item['quantity']
    discount_code = input(""Enter a discount code (or 'none' if none): "")
    if discount_code.lower() == 'bulk':
        total_cost *= 0.9
    elif discount_code.lower() == 'special':
        for item in cart.values():
            if item_name.lower() == 'special_item':
                total_cost *= 0.8
                break
    print(f""Total cost: ${total_cost:.2f}"")

