import json
from abc import ABC, abstractmethod

class Node(ABC):
    @abstractmethod
    def get_info(self):
        pass

class NetworkSimulator:
    registry = {}

    @classmethod
    def register_factory(cls, factory_id, factory_func):
        cls.registry[factory_id] = factory_func

    @classmethod
    def from_json(cls, json_string):
        try:
            return eval('cls.' + json_string['type'] + '(**json_string[""data""])')
        except KeyError as e:
            raise ValueError(f""Invalid JSON: {e}"")
        except Exception as e:
            raise ValueError(f""Failed to instantiate node: {e}"")

    @classmethod
    def simulate_traffic(cls, config_file):
        with open(config_file, 'r') as f:
            config = json.load(f)

        if 'nodes' not in config or 'max_connections' not in config or 'latency' not in config:
            raise ValueError(""Invalid configuration file"")

        for node_config in config['nodes']:
            node_id = node_config['id']
            node_type = node_config.get('type', '')
            node_data = node_config.get('data', {})

            if node_type and node_type in cls.registry:
                node = cls.registry[node_type](**node_data)
                print(f""Instantiated {node_type} with id: {node_id}, info: {node.get_info()}"")
            else:
                raise ValueError(f""Unknown node type: {node_type}"")

