import json
from abc import ABCMeta, abstractmethod

class NetworkSimulator:
    _registry = {}
    def __init__(self):
        self._registry['node'] = self._create_node
        self._registry['switch'] = self._create_switch
        self._registry['router'] = self._create_router

    def add_factory(self, id: str, factory_func):
        if not callable(factory_func):
            raise ValueError(""Factory function must be a callable"")
        self._registry[id] = factory_func

    @abstractmethod
    class Node(metaclass=ABCMeta):
        @abstractmethod
        def __init__(self):
            pass

    @abstractmethod
    class Switch(metaclass=ABCMeta):
        @abstractmethod
        def __init__(self):
            pass

    @abstractmethod
    class Router(metaclass=ABCMeta):
        @abstractmethod
        def __init__(self):
            pass

    def _create_node(self, **kwargs):
        return Node(**kwargs)

    def _create_switch(self, **kwargs):
        return Switch(**kwargs)

    def _create_router(self, **kwargs):
        return Router(**kwargs)

    def simulate_traffic(self, config_file):
        with open(config_file) as f:
            data = json.load(f)

        network_components = {}
        for component in data['components']:
            node_type = component['type']
            if node_type not in self._registry:
                raise ValueError(""Invalid node type"")
            factory_func = self._registry[node_type]
            network_components[component['id']] = factory_func(**component.get('params', {}))

        return network_components
