import requests
import jsonschema
from jsonschema import validate
from getpass import getpass
import os


def validate_api_key(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            data = response.json()
            schema_path = 'path_to_your_schema_file.json'  # update this to your schema file path
            with open(schema_path) as f:
                schema = json.load(f)

            try:
                validate(instance=data, schema=schema)
                api_key = data['api_key']
                config_path = '.config.json'
                if not os.path.isfile(config_path):
                    with open(config_path, 'w') as f:
                        json.dump({'api_key': api_key}, f)
                else:
                    existing_config = json.load(open(config_path))
                    if existing_config['api_key'] != api_key:
                        with open(config_path, 'w') as f:
                            json.dump({'api_key': api_key}, f)

            except jsonschema.exceptions.ValidationError as e:
                print(f""Invalid response: {e}"")

        else:
            print(f""Failed to retrieve data. Status code: {response.status_code}"")
    except requests.exceptions.RequestException as e:
        print(f""Error making request: {e}"")


if __name__ == ""__main__"":
    url = input(""Enter the API endpoint URL: "")
