def calculate_cart_cost():
    cart = {}
    while True:
        item = input(""Enter item name (or 'done' if finished): "")
        if item.lower() == 'done':
            break
        try:
            price = float(input(f""Enter {item} price: ""))
            quantity = int(input(f""Enter {item} quantity: ""))
        except ValueError:
            print(""Invalid input. Please enter numeric values."")
            continue

        cart[item] = {""price"": price, ""quantity"": quantity}

    total_cost = 0
    for item, details in cart.items():
        cost = details[""price""] * details[""quantity""]
        total_cost += cost
        if item.lower() == 'apple' and details[""quantity""] > 5:
            total_cost -= (details[""price""] * details[""quantity""]) * 0.1
        elif item.lower() == 'book' and details[""quantity""] > 10:
            total_cost -= (details[""price""] * details[""quantity""]) * 0.05

    print(f""Total cart cost: ${total_cost:.2f}"")

