```python
import csv
from openpyxl import Workbook

def convert_csv_to_excel(input_file, output_file):
    wb = Workbook()
    ws = wb.active

    with open(input_file, 'r') as f:
        reader = csv.reader(f)

        for row in reader:
            ws.append(row)

    wb.save(output_file)

if __name__ == '__main__':
    import sys
    if len(sys.argv) != 3:
        print(""Usage: python csv_to_excel.py <input.csv> <output.xlsx>"")
        exit(1)
    convert_csv_to_excel(sys.argv[1], sys.argv[2])
