import hashlib
def get_sha256_hash(file_path):
    chunk_size = 65536
    sha256_hash = hashlib.sha256()

    with open(file_path, 'rb') as file:
        while True:
            file_chunk = file.read(chunk_size)
            if not file_chunk:
                break
            sha256_hash.update(file_chunk)

    return sha256_hash.hexdigest()
