import csv
import json
import xml.etree.ElementTree as ET
import sys

def read_csv(csv_path):
    with open(csv_path, 'r') as file:
        reader = csv.DictReader(file)
        return [row for row in reader]

def filter_data(data, conditions):
    result = []
    for row in data:
        is_filtered = True
        for condition in conditions:
            if eval(condition):
                is_filtered = False
                break
        if not is_filtered:
            result.append(row)
    return result

def transform_data(data, transformations):
    result = data[:]
    for transformation in transformations:
        if transformation[0] == 'sort':
            key = transformation[1]
            result.sort(key=lambda x: x[key])
        elif transformation[0] == 'filter':
            condition = transformation[1]
            result = [row for row in result if eval(condition)]
        elif transformation[0] == 'map':
            mapping = transformation[1]
            for row in result:
                for key, value in mapping.items():
                    row[key] = value.get(row[key], row[key])
    return result

def output_data(data, output_format):
    if output_format == 'json':
        return json.dumps([dict((k, v) for k, v in row.items()) for row in data])
    elif output_format == 'xml':
        root = ET.Element('root')
        for row in data:
            item = ET.SubElement(root, 'item')
            for key, value in row.items():
                ET.SubElement(item, key).text = str(value)
        return ET.tostring(root, encoding='unicode')

def main():
    if len(sys.argv) != 4:
        print('Usage: python program.py <csv_path> <output_format> <conditions>')
        sys.exit(1)

    csv_path = sys.argv[1]
    output_format = sys.argv[2]
    conditions = [condition.strip() for condition in sys.argv[3].split(',')]

    data = read_csv(csv_path)
    filtered_data = filter_data(data, conditions)
    transformed_data = transform_data(filtered_data, [
        ['sort', 'column'],
        ['filter', 'condition'],
        # Add more transformations as needed
    ])
    output = output_data(transformed_data, output_format)

    print(output)

if __name__ == '__main__':
    main()
