import csv
from functools import reduce, partial
import operator

def parse_arguments():
    parser = argparse.ArgumentParser(description=""Merge multiple CSV files and transform their data."")
    parser.add_argument(""csv_files"", nargs=""+"", help=""Paths to input CSV files"")
    parser.add_argument(""-o"", ""--output_format"", choices=[""json"", ""xml""], default=""json"",
                        help=""Output format (JSON or XML)"")
    parser.add_argument(""-f"", ""--filter_conditions"", action=""append"",
                        help=""Filter conditions in the form of 'key=value' (can be used multiple times)"")
    parser.add_argument(""--aggregate_by"", type=str,
                        help=""Aggregate by this key (only applicable when using --output_format json)"")
    return parser.parse_args()

def read_csv(file_path):
    result = []
    with open(file_path) as csv_file:
        reader = csv.DictReader(csv_file)
        result.extend(reader)
    return result

def apply_filter(data_list, filter_conditions):
    if not filter_conditions:
        return data_list

    filters = {}
    for condition in filter_conditions:
        key_value = condition.split(""="")
        if len(key_value) != 2:
            raise ValueError(""Invalid filter condition: {}"".format(condition))
        filters[key_value[0]] = key_value[1]

    filtered_data = []
    for item in data_list:
        matches_all_filters = True
        for key, value in filters.items():
            if item.get(key) != value:
                matches_all_filters = False
                break
        if matches_all_filters:
            filtered_data.append(item)

    return filtered_data

def apply_sort(data_list, sort_key):
    return sorted(data_list, key=lambda x: x[sort_key])

def apply_aggregate(data_list, aggregate_by):
    result = {}
    for item in data_list:
        key = item.get(aggregate_by)
        if key not in result:
            result[key] = []
        result[key].append(item)
    return list(result.values())

def apply_transform(data_list, transform_function):
    return [transform_function(item) for item in data_list]

def to_json(data_list, output_format=""json""):
    return json.dumps([dict((k,v)) for d in [dict(zip(map(lambda x: x.split('.'), item.keys())) if isinstance(item, dict) else item for item in data_list))], indent=4)

def to_xml(data_list):
    root = ET.Element(""root"")
    for item in data_list:
        child = ET.SubElement(root, ""item"")
        for key, value in item.items():
            ET.SubElement(child, key).text = str(value)
    return ET.tostring(root, encoding=""unicode"")

def main():
    args = parse_arguments()
    merged_data = []
    for file_path in args.csv_files:
        data = read_csv(file_path)
        if args.filter_conditions:
            data = apply_filter(data, args.filter_conditions)
        if args.aggregate_by:
            data = apply_aggregate(data, args.aggregate_by)
        if args.output_format == ""json"":
            data = [dict((k,v)) for d in [dict(zip(map(lambda x: x.split('.'), item.keys())) if isinstance(item, dict) else item for item in data))]
        merged_data.extend(data)

    if args.filter_conditions:
        merged_data = apply_filter(merged_data, args.filter_conditions)

    if args.sort_key:
        merged_data = apply_sort(merged_data, args.sort_key)

    if args.transform_function:
        merged_data = apply_transform(merged_data, partial(args.transform_function))

    if args.output_format == ""json"":
        print(to_json(merged_data))
    elif args.output_format == ""xml"":
        print(to_xml(merged_data).decode(""utf-8""))

if __name__ == ""__main__"":
    main()
