from graphlib import Graph
import os
import time
import random

class StreamFileHandler:
    def __init__(self, file_path):
        self.graph = Graph()
        self.file_path = file_path
        self.sequence_number = None

    def read_file(self):
        if not os.path.exists(self.file_path):
            return None

        with open(self.file_path, 'r') as f:
            lines = f.readlines()

        if len(lines) > 0:
            self.sequence_number = int(lines[-1].strip())

    def sort_lines(self):
        # implement sorting logic here
        pass

    def add_random_vertices(self):
        if not self.graph:
            return None

        for _ in range(10):  # add random vertices
            vertex_id = f""V{random.randint(0,100)}""
            self.graph.add_vertex(vertex_id)

    def add_random_edges(self):
        if not self.graph:
            return None

        for _ in range(10):  # add random edges
            start_node = random.choice(list(self.graph))
            end_node = random.choice([node for node in self.graph if node != start_node])
            self.graph.add_edge(start_node, end_node)

    def get_vertices(self):
        return list(self.graph)

    def initiate_streaming_process(self):
        while True:
            time.sleep(5)  # wait 5 seconds before adding a new vertex and edge

            if not self.sequence_number:
                self.read_file()

            if self.sequence_number:
                for _ in range(10):  # add random vertices
                    vertex_id = f""V{random.randint(0,100)}""
                    self.graph.add_vertex(vertex_id)
                for _ in range(10):  # add random edges
                    start_node = random.choice(list(self.graph))
                    end_node = random.choice([node for node in self.graph if node != start_node])
                    self.graph.add_edge(start_node, end_node)

    def run(self):
        self.read_file()
        while True:
            initiate_streaming_process()
