from ftplib import FTP
from ftplib import ALLDATA
import logging

def ftp_operations(host='ftp.example.com', username='anonymous', password='', port=21):
    log = logging.getLogger()
    log.setLevel(logging.INFO)
    handler = logging.StreamHandler()
    log.addHandler(handler)

    try:
        ftp_connection = FTP(host, timeout=10)
        ftp_connection.login(username, password)

        transferred_files = {}
        interaction_log = []

        while True:
            command = input(""Enter a command (e.g., get file.txt, quit): "")

            if command.lower() == 'quit':
                break

            try:
                ftp_connection.retrlines('LIST', lambda line: print(line))

                if 'file.txt' in [line[4:].strip() for line in ftp_connection.retrlines('LIST')]:
                    file_data = ftp_connection.retrbinary('RETR file.txt', open('file.txt', 'wb').write)
                    transferred_files['file.txt'] = file_data
                else:
                    log.info(""File not found."")
            except ftplib.allpreadtimeout as e:
                log.error(f""Timeout error: {e}"")
            except ftplib.ftpcall as e:
                log.error(f""FTP call error: {e}"")
            except Exception as e:
                log.error(f""An unexpected error occurred: {e}"")

            interaction_log.append(command)

        ftp_connection.quit()
        return {'transferred_files': transferred_files, 'interaction_log': interaction_log}

    except ftplib.allpreadtimeout as e:
        log.error(f""Timeout error: {e}"")
    except ftplib.ftpcall as e:
        log.error(f""FTP call error: {e}"")
    except Exception as e:
        log.error(f""An unexpected error occurred: {e}"")

    return {'transferred_files': {}, 'interaction_log': []}
