```python
import xml.etree.ElementTree as ET

def parse_xml(xml_string):
    root = ET.fromstring(xml_string)
    data_dict = {}
    def traverse(node, parent=None):
        if parent is not None:
            key = ""."".join([str(x) for x in parent] + [node.tag])
            if node.text:
                data_dict[key] = node.text.strip()
            else:
                data_dict[key] = {}
                for child in node:
                    traverse(child, parent+[(child.tag,)])
        else:
            for child in root:
                traverse(child)
    traverse(root)
    return data_dict
```

