from Cryptodome.Cipher import AES
from Cryptodome.Util.Padding import pad, unpad
import base64
import os

def encrypt_data(plaintext: bytes, secret_key: bytes, iv: bytes = None):
    if len(secret_key) not in [16, 24, 32]:
        raise ValueError(""Key length must be 128, 192, or 256 bits"")
    if iv is not None and len(iv) != 16:
        raise ValueError(""Invalid IV format. IV must be 128 bits (16 bytes)"")

    cipher = AES.new(secret_key, AES.MODE_CBC, iv)
    ciphertext = cipher.encrypt(pad(plaintext, AES.block_size))
    return base64.b64encode(ciphertext).decode('utf-8')

def decrypt_data(ciphertext: str, secret_key: bytes, iv: bytes):
    if len(secret_key) not in [16, 24, 32]:
        raise ValueError(""Key length must be 128, 192, or 256 bits"")
    if iv is None:
        raise ValueError(""IV is required for decryption"")

    cipher = AES.new(secret_key, AES.MODE_CBC, iv)
    decrypted_text = unpad(cipher.decrypt(base64.b64decode(ciphertext)), AES.block_size).decode('utf-8')
    return decrypted_text
