import random
import json
from abc import ABC, abstractmethod

class FactoryFunction(ABC):
    @abstractmethod
    def generate_instance(self, **kwargs):
        pass

class Registry:
    _registry = {}
    _default_factory = None

    def register(self, name: str, factory_function: FactoryFunction):
        self._registry[name] = factory_function

    def get_factory(self, name: str):
        return self._registry.get(name, self._default_factory)

class RandomGraph:
    def __init__(self):
        self.registry = Registry()

    def generate_random_label(self, n):
        return str(random.randint(0, n - 1))

    def generate_edges(self, n, m):
        nodes = {i: {} for i in range(n)}
        for _ in range(m):
            node1 = random.randint(0, n - 1)
            node2 = random.randint(0, n - 1)
            weight = random.random()
            if node1 != node2:
                nodes[node1][node2] = {'weight': weight}
                if not node2 in nodes[node1]:
                    nodes[node1][node2] = {'weight': weight}
        return nodes

    def to_json(self, graph):
        return json.dumps(graph)

    @classmethod
    def from_json(cls, json_data):
        data = json.loads(json_data)
        return cls().generate_instances(data)

    def add_factory(self, name: str, factory_function: FactoryFunction):
        self.registry.register(name, factory_function)
