            # Calculate statistical summaries
            mean_values = chunk['Field1'].mean()
            median_values = chunk['Field2'].median()
            logging.info(f""Mean: {mean_values}, Median: {median_values}"")

    except (ValueError, FileNotFoundError) as e:
        logging.error(f""An error occurred: {e}"")

def main():
