class Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.left = None
        self.right = None


class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key, value):
        if not self.root:
            self.root = Node(key, value)
        else:
            self._insert(self.root, key, value)

    def _insert(self, node, key, value):
        if key < node.key:
            if node.left:
                self._insert(node.left, key, value)
            else:
                node.left = Node(key, value)
        elif key > node.key:
            if node.right:
                self._insert(node.right, key, value)
            else:
                node.right = Node(key, value)
        else:
            node.value = value

    def delete(self, key):
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if not node:
            return None
        if key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            if not node.left and not node.right:
                return None
            elif not node.left:
                return node.right
            elif not node.right:
                return node.left
            min_node = self._min_value_node(node.right)
            node.key = min_node.key
            node.value = min_node.value
            node.right = self._delete(node.right, node.key)
        return node

    def _min_value_node(self, node):
        current = node
        while current.left:
            current = current.left
        return current

    def find_min_key(self):
        if not self.root:
            return None
        return self._find_min_key(self.root)

    def _find_min_key(self, node):
        if not node.left:
            return node.key
        return self._find_min_key(node.left)

    def find_max_key(self):
        if not self.root:
            return None
        return self._find_max_key(self.root)

    def _find_max_key(self, node):
        if not node.right:
            return node.key
        return self._find_max_key(node.right)

    def search(self, key):
        return self._search(self.root, key)

    def _search(self, node, key):
        if not node or node.key == key:
            return node.value if node else None
        if key < node.key:
            return self._search(node.left, key)
        return self._search(node.right, key)
