def hmac_with_key_stretching(key, message, hash_function=hashlib.sha256, num_iterations=1000):
    key = bytes.fromhex(key)
    for _ in range(num_iterations):
        key = hash_function(key).digest()
    return hashlib.new(hash_function.name, (key + message).encode()).hexdigest()

def combine_key_message(key, message, salt):
