def modifyFilenameExtension(filename, new_extension):
    if not os.path.exists(filename):
        return ""FILE_NOT_FOUND""

    path, file_name = os.path.split(filename)
    if os.path.isdir(path):
        return ""FILE_EXT_ERROR""

    modified_filename = os.path.join(path, file_name.rsplit('.', 1)[0] + new_extension)

    try:
        with open(filename, 'rb') as f_in, open(modified_filename, 'wb') as f_out:
            f_out.write(f_in.read())
    except Exception as e:
        return str(e)

    return modified_filename, ""SUCCESS""
