            if set(['Date', 'Stock Price', 'Volume']).issubset(set(reader.fieldnames)):
                for row in reader:
                    date = datetime.datetime.strptime(row['Date'], '%Y-%m-%d')
                    previous_price = None
                    for i, row in enumerate(reader):
                        if i == 0:
                            continue
                        current_date = datetime.datetime.strptime(row['Date'], '%Y-%m-%d')
                        stock_price = float(row['Stock Price'])
                        change = (stock_price - previous_price) / previous_price * 100 if previous_price else float('nan')
                        if abs(change) > 5:  # specify your desired threshold here
                            print(f""{date}: {previous_price} -> {stock_price}, Change: {change:.2f}%"")
                        previous_price = stock_price
            else:
                print(""Invalid CSV file. Expected columns 'Date', 'Stock Price', and 'Volume'."")
    except FileNotFoundError:
        print(""CSV file not found."")
    except Exception as e:
        print(f""An error occurred: {e}"")

# usage
calculate_daily_change('stock_data.csv')
