class Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.left = None
        self.right = None
        self.height = 1


class AVLTree:
    def __init__(self):
        self.root = None

    def insert(self, key, value):
        if not self.root:
            self.root = Node(key, value)
        else:
            self.root = self._insert(self.root, key, value)

        return self.root

    def _insert(self, node, key, value):
        if not node:
            return Node(key, value)

        if key < node.key:
            node.left = self._insert(node.left, key, value)
        elif key > node.key:
            node.right = self._insert(node.right, key, value)
        else:
            node.value = value

        return self._rebalance(self._update_height(node))

    def delete(self, key):
        if not self.root:
            return None
        else:
            self.root = self._delete(self.root, key)

        return self.root

    def _delete(self, node, key):
        if not node or node.key != key:
            return node

        if node.left and node.right:
            if node.left.height > node.right.height:
                node = self._right_rotate(node)
            else:
                node = self._left_rotate(node)

        child = node.left if node.left else node.right
        node = None if not child else child

        return self._rebalance(self._update_height(node))

    def search(self, key):
        if not self.root or not self._search(self.root, key):
            return None

        return self.root.value

    def _search(self, node, key):
        if not node:
            return False
        elif node.key == key:
            return True
        elif key < node.key:
            return self._search(node.left, key)
        else:
            return self._search(node.right, key)

    def find_min(self):
        current = self.root
        while current and current.left:
            current = current.left

        return current.value if current else None

    def find_max(self):
        current = self.root
        while current and current.right:
            current = current.right

        return current.value if current else None

    def _rebalance(self, node):
        balance_factor = self._get_balance_factor(node)

        if balance_factor > 1:
            if self._get_height(node.left) > self._get_height(node.left.left):
                node = self._right_rotate(node)
            else:
                node = self._left_rotate(node)

        elif balance_factor < -1:
            if self._get_height(node.right) > self._get_height(node.right.right):
                node = self._left_rotate(node)
            else:
                node = self._right_rotate(node)

        return node

    def _update_height(self, node):
        node.height = max(self._get_height(node.left), self._get_height(node.right)) + 1
        return node

    def _get_balance_factor(self, node):
        return self._get_height(node.left) - self._get_height(node.right)

    def _get_height(self, node):
        return node.height if node else 0

    def _left_rotate(self, node):
        new_root = node.right
        node.right = new_root.left
        new_root.left = node
        node.height = self._update_height(node)
        new_root.height = self._update_height(new_root)

        return new_root

    def _right_rotate(self, node):
        new_root = node.left
        node.left = new_root.right
        new_root.right = node
        node.height = self._update_height(node)
        new_root.height = self._update_height(new_root)

        return new_root

    def find_kth_smallest(self, k):
        if not self.root:
            return None

        stack = []
        while True:
            while self.root and self.root.left:
                self.root = self.root.left
            if not self.root:
                break
            stack.append(self.root.value)
            self.root = self.root.right

        for _ in range(k - 1):
            stack.pop()

        return stack.pop() if k <= len(stack) else None
