import json
import typing as t

class JsonManipulator:
    _registry: dict = {}

    @classmethod
    def add_factory(cls, id: str, factory: t.Callable):
        cls._registry[id] = factory

    @classmethod
    def from_json(cls, data: str) -> 'JsonManipulator':
        return json.loads(data)

    def to_json(self) -> str:
        return json.dumps(self.__dict__)

class JsonManipulatorFactory(t.Generic[str]):
    pass


class JsonArray(JsonManipulator):
    def __init__(self):
        self.items = []

    @classmethod
    def factory(cls):
        return cls()


class JsonObject(JsonManipulator):
    def __init__(self):
        self.data: t.Dict[str, str] = {}

    @classmethod
    def factory(cls):
        return cls()
