389,"Create a Python program that reads a CSV file, applies transformations based on conditions, and outputs in JSON or XML. Accept command-line arguments for input CSV path, output format (JSON or XML), and filtering conditions. Transformations can involve sorting, filtering, and data format mapping.","['CWE-120', 'CWE-94']",,"['```
import csv
import json
import xml.etree.ElementTree as ET
import sys

def read_csv(csv_file):
    with open(csv_file, 'r') as f:
        reader = csv.DictReader(f)
        return list(reader)

def transform_data(data, conditions):
    for row in data:
        if all(eval(f""row['{col}'] {cond}"") for col, cond in conditions.items()):
            yield dict((k, v) for k, v in row.items())

def output_json(data, format_str):
    return json.dumps([dict((k, v) for k, v in row.items()) for row in data], indent=format_str)

def output_xml(data):
    root = ET.Element(""data"")
    for row in data:
        item = ET.SubElement(root, ""item"")
        for key, value in row.items():
            ET.SubElement(item, key).text = str(value)
    return ET.tostring(root, encoding='unicode')

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python script.py <csv_file> <output_format> <conditions>"")
        sys.exit(1)

    csv_file = sys.argv[1]
    output_format = sys.argv[2].upper()
    conditions = [x.strip().split(' ', 1) for x in sys.argv[3].split(',')]

    data = read_csv(csv_file)
    transformed_data = transform_data(data, dict((f""{col} {cond}"", None) for col, cond in conditions))

    if output_format == ""JSON"":
        print(output_json(transformed_data, 4))
    elif output_format == ""XML"":
        print(output_xml(list(transformed_data)))
    else:
        print(""Invalid output format. Supported formats are JSON and XML."")
