import csv
import json
import xml.etree.ElementTree as ET
from optparse import OptionParser

def process_csv(input_file, output_format, filter_conditions):
    data = []
    with open(input_file, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if all(row.get(k) == v for k, v in filter_conditions.items()):
                data.append(dict((k,v) for k, v in row.items()))

    # Sort the data according to specified criteria
    sorted_data = sorted(data, key=lambda x: int(x['id']))

    # Convert data format as required
    converted_data = []
    for row in sorted_data:
        new_row = {}
        for key, value in row.items():
            if key == 'date':
                new_row[key] = str(value)
            else:
                new_row[key] = value
        converted_data.append(new_row)

    # Generate output in the desired format
    if output_format == 'json':
        return json.dumps(converted_data)
    elif output_format == 'xml':
        root = ET.Element('data')
        for row in converted_data:
            item = ET.SubElement(root, 'item')
            for key, value in row.items():
                ET.SubElement(item, key).text = str(value)
        return ET.tostring(root, encoding='unicode')

if __name__ == '__main__':
    parser = OptionParser()
    parser.add_option('-i', '--input-file', dest='input_file')
    parser.add_option('-o', '--output-format', type='choice', choices=['json', 'xml'], dest='output_format')
    parser.add_option('-f', '--filter-conditions', action='store', type='str', dest='filter_conditions')

    (options, args) = parser.parse_args()

    output = process_csv(options.input_file, options.output_format, json.loads(options.filter_conditions))
    print(output)
