import json
import random
from dataclasses import dataclass

@dataclass
class NCRP:
    nii: str
    spi: str
    registration_id: int
    ak: str = None

def generate_ncrp_list(num_entities):
    return [NCRP(
        nii=f""NI-{random.randint(1, 1000)}"",
        spi=f""SP-{random.randint(1, 1000)}"",
        registration_id=random.randint(1, 1000),
        ak=f""AK-{random.randint(1, 1000)}"" if random.random() < 0.5 else None
    ) for _ in range(num_entities)]

def validate_json(json_string):
    try:
        data = json.loads(json_string)
        required_fields = [""nii"", ""spi"", ""registration_id""]

        if all(field in data for field in required_fields):
            return True
        else:
            return False

    except json.JSONDecodeError:
        return False

