import json
import random

class NCRP:
    def __init__(self, nii, spi, registration_id, auth_key=None):
        self.nii = nii
        self.spi = spi
        self.registration_id = registration_id
        self.auth_key = auth_key if auth_key else self.generate_auth_key()

    def generate_auth_key(self):
        return ''.join([chr(random.randint(33, 126)) for _ in range(16)])

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_info_tag, rnti, crcflag, int_value=None,
                 offset_value=None, key_value=None):
        self.rx_ue_info_tag = rx_ue_info_tag
        self.rnti = rnti
        self.crcflag = crcflag if crcflag is not None else bool(random.getrandbits(1))
        self.int_value = int_value if int_value is not None else random.randint(0, 99)
        self.offset_value = offset_value if offset_value is not None else random.randint(0, 999)
        self.key_value = key_value if key_value is not None else (random.randint(0, 255))

def validate_device_registration(json_str):
    data_dict = json.loads(json_str)
    required_fields = ['NII', 'SPI', 'RegistrationID']
    return all(field in data_dict for field in required_fields)

def generate_device_registration_data():
