import requests
import json
import logging

def fetchWebPageContent(url):
    try:
        response = requests.get(url)
        return response.text
    except Exception as e:
        logging.error(f""Error fetching web page content: {e}"")

def parseJsonData(html_content):
    try:
        data = {}
        start_index = html_content.find('{')
        end_index = html_content.rfind('}')
        if start_index != -1 and end_index != -1:
            data = json.loads(html_content[start_index:end_index+1])
        return data
    except Exception as e:
        logging.error(f""Error parsing JSON data: {e}"")

def writeToFile(data, file_path):
    try:
        with open(file_path, 'w') as f:
            json.dump(data, f)
    except Exception as e:
        logging.error(f""Error writing to file: {e}"")

async def processWebPageAndSaveData(url, file_path):
    html_content = fetchWebPageContent(url)
    data = parseJsonData(html_content)
    if data:
        logging.info(""JSON data parsed successfully"")
        writeToFile(data, file_path)
        logging.info(f""Data saved to {file_path} successfully"")']",1,[0],[],True,0,0,0,

