    employee_profiles = []

    for _ in range(num_employees):
        id = len(employee_profiles) + 1
        full_name = ''.join(random.choice(ascii_lowercase) for _ in range(random.randint(2, 10)))
        while sum(full_name.count(v) for v in vowels) < random.randint(1, max_vowels):
            full_name = ''.join(random.choice(ascii_lowercase) for _ in range(random.randint(2, 10)))

        department = random.choices(departments, weights=department_probabilities)[0]
