                    if char in vowels:
                        current_vowel_sequence += 1
                        if current_vowel_sequence > max_vowel_sequence:
                            max_vowel_sequence = current_vowel_sequence
                    else:
                        current_vowel_sequence = 0
                    word = char.strip()
                    if word not in word_count:
                        word_count[word] = 1
                    else:
