// Python script to generate access tokens
import json
import os
from cryptography.fernet import Fernet
from datetime import datetime, timedelta

def generate_access_tokens(json_file):
    # Load user account information from the JSON file
    with open(json_file, 'r') as f:
        users = json.load(f)

    # Create a dictionary to store access tokens for each user
    access_tokens = {}

    # Iterate through the list of users and create unique access tokens
    for user in users:
        username = user['username']
        role = user['role']

        # Generate an access token with an expiration date tied to the user's role
        if role == 'admin':
            expiration_date = datetime.now() + timedelta(days=7)
        else:
            expiration_date = datetime.now() + timedelta(days=1)

        # Create a unique access token for each user
        key = Fernet.generate_key()
        cipher_suite = Fernet(key)
        token = cipher_suite.encrypt(json.dumps({'username': username, 'role': role}).encode())

        # Store the access token in the dictionary
        access_tokens[username] = {
            'token': token.decode(),
            'expiration_date': expiration_date.isoformat()
        }

    return access_tokens

