import socket
import threading

class UDP_ServerHandler:
    def __init__(self, ip_address, port):
        self.ip_address = ip_address
        self.port = port
        self.server_socket = None
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            self.server_socket.bind((ip_address, int(port)))
        except Exception as e:
            print(f""Error initializing server: {e}"")

    def start_listening(self):
        if not self.server_socket:
            return
        try:
            while True:
                data, address = self.server_socket.recvfrom(1024)
                message = data.decode(""utf-8"")
                # Handle received message from client
                print(f""Received message from {address}: {message}"")
        except Exception as e:
            print(f""Error listening: {e}"")

    def broadcast_message(self, message):
        if not self.server_socket:
            return
        try:
            for _ in range(1):  # Broadcast to all connected clients (assuming one client)
                self.server_socket.sendto(message.encode(""utf-8""), ("""", 0))  # Broadcast to all devices on the network
        except Exception as e:
            print(f""Error broadcasting: {e}"")

    def run(self):
        threading.Thread(target=self.start_listening).start()

def main():
    server_handler = UDP_ServerHandler(""127.0.0.1"", ""12345"")
    if not server_handler.server_socket:
        print(""Server initialization failed."")
        return

    # Start the server
    server_thread = threading.Thread(target=server_handler.run)
    server_thread.start()

    while True:
        command = input(""Enter a command: "")
        if command.startswith(""send""):
            message = "" "".join(command.split()[1:])
            server_handler.broadcast_message(message)
        elif command.startswith(""broadcast""):
            message = "" "".join(command.split()[1:])
            print(f""Broadcasting message to all clients: {message}"")
            server_handler.broadcast_message(message)
        elif command == ""terminate"":
            break
        else:
            print(""Invalid command. Try 'send <message>', 'broadcast <message>', or 'terminate'."")

    # Terminate the server
    server_thread.join()
    server_handler.server_socket.close()

if __name__ == ""__main__"":
    main()
